import { lazy, Suspense, useRef } from 'react';
import { useInView } from 'framer-motion';
import { Link } from 'react-router-dom';
import { useSite } from '../context';
import { TiltCard } from './motion';
import { ArrowIcon, ExternalIcon, GitHubIcon, LockIcon, PlayIcon } from './Icons';

export function Tag({ children }) {
  return <span className="tag">{children}</span>;
}

export function TagList({ items }) {
  return (
    <div className="tag-list">
      {items.map((item) => (
        <Tag key={item}>{item}</Tag>
      ))}
    </div>
  );
}

// three.js is heavy: the robot scene lives in its own chunk, loaded after the page.
const RobotStage = lazy(() => import('./Robot3D'));

// 3D robot doing something different on each page; it only animates while visible.
export function RobotSlot({ mode, className = '' }) {
  const { theme } = useSite();
  const ref = useRef(null);
  const visible = useInView(ref, { margin: '120px' });
  return (
    <div ref={ref} className={`robot-slot robot-slot--${mode} ${className}`}>
      <Suspense fallback={null}>
        <RobotStage mode={mode} theme={theme} active={visible} />
      </Suspense>
    </div>
  );
}

export function PageHeader({ eyebrow, title, lead, robot }) {
  return (
    <header className={`page-header container reveal ${robot ? 'page-header--robot' : ''}`}>
      <div>
        {eyebrow && <p className="eyebrow">{eyebrow}</p>}
        <h1 className="page-title">{title}</h1>
        {lead && <p className="page-lead">{lead}</p>}
      </div>
      {robot && <RobotSlot mode={robot} />}
    </header>
  );
}

export function SectionTitle({ eyebrow, title, action }) {
  return (
    <div className="section-title">
      <div>
        {eyebrow && <p className="eyebrow">{eyebrow}</p>}
        <h2>{title}</h2>
      </div>
      {action}
    </div>
  );
}

// Project screenshot, or a coloured panel with the project icon when there is none
// (private company code). Decorative placeholders are hidden from screen readers.
export function ProjectImage({ project, className = '' }) {
  const { lang } = useSite();
  if (project.image) {
    return (
      <div className={`project-img ${className}`}>
        <img src={`${process.env.PUBLIC_URL}/${project.image.src}`} alt={project.image.alt[lang]} loading="lazy" width="698" height="350" />
      </div>
    );
  }
  return (
    <div className={`project-img project-img--empty ${className}`} aria-hidden="true">
      <span>{project.icon}</span>
    </div>
  );
}

export function ProjectCard({ project }) {
  const { lang, t } = useSite();
  const p = t.projects;
  return (
    <TiltCard as="article" className="card project-card">
      <ProjectImage project={project} className="project-card__img" />
      <Link to={`/projects/${project.id}`} className="project-card__main">
        <div className="project-card__top">
          <span className="project-card__icon" aria-hidden="true">
            {project.icon}
          </span>
          <span className="project-card__cat">{p.filters[project.category]}</span>
        </div>
        <h3 className="project-card__title">
          {project.title[lang]}
          <ArrowIcon className="project-card__arrow" width={18} height={18} />
        </h3>
        <p className="project-card__desc">{project.desc[lang]}</p>
        {project.result && (
          <p className="project-card__result">
            <span className="project-card__result-label">✓ {p.result}</span>
            {project.result[lang]}
          </p>
        )}
        <TagList items={project.tags} />
      </Link>
      <div className="project-card__links">
        {project.live && (
          <a href={project.live} target="_blank" rel="noreferrer" className="link-chip">
            <ExternalIcon width={15} height={15} /> {p.live}
          </a>
        )}
        {project.demo && (
          <Link to={`/play/${project.demo}`} className="link-chip link-chip--accent">
            <PlayIcon width={15} height={15} /> {p.play}
          </Link>
        )}
        {project.code && (
          <a href={project.code} target="_blank" rel="noreferrer" className="link-chip">
            <GitHubIcon width={15} height={15} /> {p.code}
          </a>
        )}
        {project.private && (
          <span className="link-chip link-chip--muted">
            <LockIcon width={15} height={15} /> {p.private}
          </span>
        )}
      </div>
    </TiltCard>
  );
}

export function CtaBanner() {
  const { u } = useSite();
  return (
    <section className="container">
      <div className="cta-banner reveal">
        <div>
          <h2>{u.ctaTitle}</h2>
          <p>{u.ctaText}</p>
        </div>
        <Link to="/contact" className="btn btn--primary">
          {u.ctaButton} <ArrowIcon width={16} height={16} />
        </Link>
      </div>
    </section>
  );
}
